import sys

def x(a):
	res = [a, 1, a + 1, 0]
	return res[a % 4]

def y(a):
	if a % 2 == 0:
		return x(a // 2) << 1
	else:
		r = 0
		if (a + 1) % 4 == 2:
			r = 1
		return (x(a // 2) << 1) + r
